"""Assistant routes generated by ANG."""

from __future__ import annotations

from fastapi import APIRouter, Depends

from app import models
from app.services.assistant import AssistantService, get_assistant_service

router = APIRouter(tags=["Assistant"])

@router.post("/assistant/chat")
async def chat_with_assistant(payload: models.ChatWithAssistantRequest, svc: AssistantService = Depends(get_assistant_service)) -> models.ChatWithAssistantResponse:
    return await svc.chat_with_assistant(payload)

